sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        if (g_form.getValue('event_status') == 'REVIEW_COMPLETED.DISCARD') {
            g_form.removeOption('discard_reason', '');
            var isMultiInstruction = g_form.getValue('index_queue_multiple').includes(',');
            if (isMultiInstruction) {
                g_form.addOption('discard_reason', 'mix_inst', 'Incorrectly Indexed as Multi Instruction');
            } else {
                g_form.removeOption('discard_reason', 'mix_inst');
            }
            if (!g_form.getValue('discard_reason')) {
                g_form.setValue('discard_reason', 'pick_rsn'); //set value 'Please select reason for discarding'
                //g_form.setMandatory('discard_reason', true);
                g_form.save();
            }
            return;
        }
        if (g_form.getValue('task_type') !== 'Maker Review')
            return;
    }
    // Parse the URL parameters to check for the 'discard_option' query parameter.
    //   var url = new URL(top.location.href);
    var param = newValue;
    if (param == 'REVIEW_COMPLETED.DISCARD') {
        g_form.setDisplay('discard_reason', true);
        g_form.removeOption('discard_reason', '');
        if (!g_form.getValue('discard_reason')) {
            g_form.setValue('discard_reason', 'pick_rsn'); //set value 'Please select reason for discarding'
            //g_form.setMandatory('discard_reason', true);
            g_form.save();
            g_form.reload();
        }
    } else
        g_form.setDisplay('discard_reason', false);
}
